// 把多段文本各自按 wrap 的规则折行，段与段之间空一行；空段保留为一个空行。
export function joinFitted(paragraphs, maxWidth) {
  return paragraphs
    .map((p) => {
      const lines = wrap(p, maxWidth);
      return lines.length === 0 ? "" : lines.join("\n");
    })
    .join("\n\n");
}

